import{_ as a,o as t,c as s,a6 as r}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Performance et travail borné","description":"","frontmatter":{"title":"Performance et travail borné","docId":"developer.performance","translationKey":"developer.performance","locale":"fr","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"04bc0a89b86724872adae3ab8ddc8e29f5517dad14d51bc103d917582cf289ae","translationRevision":"c967a02ac02b2dddadbeb2911dccf631f1b2d5b5dab113b661361fd4fa031c11","order":110},"headers":[],"relativePath":"fr/developer/performance.md","filePath":"fr/developer/performance.md","lastUpdated":1794611623000}'),i={name:"fr/developer/performance.md"};function n(o,e,l,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="performance-and-bounded-work" tabindex="-1">Performance et travail borné <a class="header-anchor" href="#performance-and-bounded-work" aria-label="Permalink to &quot;Performance et travail borné {#performance-and-bounded-work}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Mesurer un goulot d’étranglement concret en préservant la comptabilisation des événements et l’arrêt. Commencez avec une compilation fixe, une entrée déterministe et un profil isolé. Lisez les <a href="./events.html">événements</a> pour ne pas confondre un flux plus rapide avec une persistance plus fiable. Les chiffres de benchmarks historiques sont des observations de leur compilation et machine nommées, pas des garanties produit actuelles.</p><h2 id="measure-the-right-boundary" tabindex="-1">Mesurer la bonne frontière <a class="header-anchor" href="#measure-the-right-boundary" aria-label="Permalink to &quot;Mesurer la bonne frontière {#measure-the-right-boundary}&quot;">​</a></h2><p>L’outbox du bureau sépare la présentation avec pertes des réponses fiables. Les instantanés peuvent être regroupés ; un débordement du canal fiable doit échouer visiblement. L’entrée LIVE, le travail des plugins, les appels des processeurs et l’admission d’automatisation ont chacun leurs limites. Agrandir une file peut déplacer la pression mémoire ou la latence vers l’étape suivante.</p><p>Le runtime de l’interface expose des diagnostics agrégés en développement ou lors d’une compilation avec <code>VITE_TIKTOOLS_DIAGNOSTICS=1</code>. Son instantané inclut les lignes rendues, percentiles d’intervalle entre trames, appels en attente du client de contrôle, images et temporisateurs possédés. Les données de tas JavaScript peuvent être indisponibles sur une WebView donnée. Les pages masquées et la visibilité de l’hôte gouvernent l’intérêt de présentation, pas la comptabilisation métier.</p><h2 id="run-a-focused-comparison" tabindex="-1">Exécuter une comparaison ciblée <a class="header-anchor" href="#run-a-focused-comparison" aria-label="Permalink to &quot;Exécuter une comparaison ciblée {#run-a-focused-comparison}&quot;">​</a></h2><ol><li>Notez la révision de compilation, la plateforme, le mélange d’événements, l’activation des images, l’onglet visible et la durée.</li><li>Établissez une référence avec la même fixture et la même période d’échantillonnage.</li><li>Modifiez une frontière, puis comparez débit, latence p95/p99, abandons de files, lacunes, mémoire conservée et vidage à l’arrêt.</li><li>Incluez un plugin ou consommateur lent et une file saturée ; un benchmark au repos ne teste pas la contre-pression.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live-feed-state</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> persistence,native-tiktok</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live_throughput</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>Examinez les exigences de fonctionnalités avant d’activer un benchmark natif ; les vérifications unitaires ciblées ordinaires ne nécessitent pas de connexion réelle à TikTok. Utilisez <code>crates/tiktools-core/tests/live_throughput.rs</code> et les tests de l’outbox du bureau comme références d’implémentation.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>Les parcours de projection et d’admission bornés sont implémentés, avec compteurs et signalement de lacunes. Le <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/services/points/queue.rs" target="_blank" rel="noreferrer">rédacteur ordonné actuel</a> rejette les écritures saturées avant de modifier la mémoire et interdit le repli vers une écriture synchrone. Les anciens rapports de performance décrivent des défauts d’ordre désormais dépassés. Évaluez les limites du cache et la récupération face aux erreurs avec l’implémentation/les tests actuels plutôt que de déduire une correction complète d’une mémoire d’interface bornée.</p><h2 id="recover" tabindex="-1">Récupérer <a class="header-anchor" href="#recover" aria-label="Permalink to &quot;Récupérer {#recover}&quot;">​</a></h2><p>Si les trames s’améliorent mais que la santé comptable se dégrade, annulez la modification de frontière et examinez les résultats d’écriture/admission. Si les temporisateurs d’onglets masqués augmentent, suivez le <a href="./lifecycle.html">nettoyage du cycle de vie</a>. Gardez dans le rapport le nombre d’entrées brutes, le nombre accepté et la classification des pertes. Une lacune peut récupérer l’état d’affichage ; elle ne répare pas un effet rejeté ou devenu incertain.</p>`,14)])])}const h=a(i,[["render",n]]);export{m as __pageData,h as default};
